[ExtensionOf(classStr(PurchCopyingForm))]
final class METPurchCopyingForm_Extension
{
    public RefRecId recordNum;
    public RefTableId tableId;

}

Method.Source:
/// <summary>
/// Gets or sets record num of last selected record in copy all form
/// </summary>
/// <param name = "_recordNum">Record id of selected record</param>
/// <returns>Record id of selected record</returns>
public RefRecId parmRecordNum(RefRecId _recordNum = recordNum)
{
    recordNum = _recordNum;
    return recordNum;
}

/// <summary>
/// Gets or sets table num of last selected record in copy all form
/// </summary>
/// <param name = "_tableId">table num of selected record</param>
/// <returns>table num of selected record</returns>
public RefRecId parmTableNum(RefRecId _tableId = tableId)
{
    tableId = _tableId;
    return tableId;
}

/// <summary>
/// Consturct purch copying
/// </summary>
/// <param name = "_tmpFrmVirtualLines">TmpFrmVirtual with lines info</param>
/// <param name = "_tmpFrmVirtualHeader">TmpFrmVirtual with header info</param>
/// <param name = "_qtyFactor">Quality factor</param>
/// <param name = "_reverseSign">Reverse sign</param>
/// <param name = "_recalculateAmount">recalculate amount</param>
/// <param name = "_copyMarkup">Copy markup</param>
/// <param name = "_copyPrecisely">copy Precisely</param>
/// <param name = "_deleteLines">Delete lines</param>
/// <param name = "_vendInvoiceJour">Vend Invoice jour</param>
public void constructAndInitCopying(TmpFrmVirtual   _tmpFrmVirtualLines,
                                    TmpFrmVirtual   _tmpFrmVirtualHeader,
                                    Qty             _qtyFactor,
                                    NoYes           _reverseSign,
                                    NoYes           _recalculateAmount,
                                    NoYes           _copyMarkup,
                                    NoYes           _copyPrecisely,
                                    NoYes           _deleteLines,
                                    VendInvoiceJour _vendInvoiceJour)
{
    if (_tmpFrmVirtualHeader == null && _copyPrecisely == NoYes::Yes)
    {
        ttsbegin;
        _tmpFrmVirtualHeader.clear();
        _tmpFrmVirtualHeader.TableNum     = tableId;
        _tmpFrmVirtualHeader.RecordNo     = recordNum;
        _tmpFrmVirtualHeader.insert();
        ttscommit;
    }

    next constructAndInitCopying(_tmpFrmVirtualLines,
                                 _tmpFrmVirtualHeader,
                                 _qtyFactor,
                                 _reverseSign,
                                 _recalculateAmount,
                                 _copyMarkup,
                                 _copyPrecisely,
                                 _deleteLines,
                                 _vendInvoiceJour);

}
